import os
import json

def main():
    # Load environment variables
    env_vars = os.environ

    # Initialize response variables
    response_from_env = {}
    oda_response_from = {}

    # Check for specific environment variables
    if 'MAI_AMFANI' in env_vars:
        response_from_env['mai_amfani'] = env_vars['MAI_AMFANI']
    if 'SIGO_MAI_AMFANI' in env_vars:
        response_from_env['sigogi'] = env_vars['SIGO_MAI_AMFANI']
    if 'MARTANI' in env_vars:
        response_from_env['martani'] = env_vars['MARTANI']
    if 'MATSAYIN_GARDAMA' in env_vars:
        response_from_env['matsayin_gardama'] = env_vars['MATSAYIN_GARDAMA']
    if 'MUHALLI' in env_vars:
        response_from_env['muhalli'] = env_vars['MUHALLI']

    # Process additional response from other sources
    if 'ODA_RESPONSE_FROM' in env_vars:
        try:
            oda_response_from = json.loads(env_vars['ODA_RESPONSE_FROM'])
        except json.JSONDecodeError:
            oda_response_from = {}

    # Combine responses
    final_response = {
        'response_from_env': response_from_env,
        'oda_response_from': oda_response_from
    }

    # Output final response
    print(json.dumps(final_response, indent=2))

if __name__ == "__main__":
    main()

